('accountability_program', 'Reclaim Accountability Partner Matching', null, 'Pairs you with a trained, same-gender accountability partner for regular check-ins.', null, '(555) 340-9981', null, null, '{}', true),
('accountability_program', 'Covenant Eyes-style Accountability Software', null, 'Screen accountability software that sends activity reports to a partner you choose.', null, 'example-accountability.test', null, null, '{}', true),
('accountability_program', 'Trusted Friend Check-In Network', null, 'A simple, low-tech option: a rotating list of volunteers willing to receive a text or call check-in from someone they don''t know personally, no software required.', null, '(555) 276-4420', null, null, '{}', true),
('accountability_program', 'Ministry Mentor Program', null, 'Pairs you with an older, more experienced mentor (not just a peer) for longer-term accountability and guidance, typically meeting every other week.', null, '(555) 918-3367', null, null, '{}', true),
('counseling_center', 'Grace & Truth Counseling Center', 'Faith-based licensed counseling', null, null, '(555) 412-8890', 'Example — Grove City, PA', null, '{}', true),
('counseling_center', 'Pure Freedom Telehealth Counseling', 'Licensed counseling, addiction-informed, telehealth', null, null, '(555) 665-3320', 'Example — Nationwide (telehealth)', null, '{}', true),
('counseling_center', 'Renewal Family Counseling', 'Licensed counseling, individual and couples', null, null, '(555) 704-2298', 'Example — Columbus, OH', null, '{}', true),
('counseling_center', 'Overcomers Telehealth Group Therapy', 'Licensed group therapy, addiction-focused, telehealth', null, null, '(555) 833-5561', 'Example — Nationwide (telehealth)', null, '{}', true);
